from collections import Counter

MOD = 10**9 + 9

def count_unsorted_permutations(n, nums):
    if len(set(nums)) == 1:
        return pow(n, n - 1, MOD)

    counter = Counter(nums)
    total = factorial(len(nums), MOD)

    for count in counter.values():
        total = mul(total, mod_inverse(factorial(count, MOD), MOD), MOD)

    return total

def factorial(x, mod):
    result = 1
    for i in range(2, x + 1):
        result = (result * i) % mod
    return result

def mod_inverse(a, mod):
    return pow(a, mod - 2, mod)

def mul(a, b, mod):
    return (a * b) % mod

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    nums = list(map(int, data[1:]))
    print(count_unsorted_permutations(n, nums))
